{"code": "import nanosurf, inspect, json
spm = nanosurf.SPM()
app = spm.application
scan = app.Scan
attrs = [a for a in dir(scan) if not a.startswith('_')]
print('Scan attributes:', attrs)
# Also show possible properties with type
props = {}
for a in attrs:
    try:
        val = getattr(scan, a)
        props[a] = type(val).__name__
    except Exception as e:
        props[a] = f'Error:{e}'
print(json.dumps(props, indent=2))

del spm"}

